import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// Relative import: drizzle-kit does not resolve the "@/" alias.
import { CONTACT_FREQUENCIES } from "../lib/keep-in-touch";

// Russian alphabetical order (the default collation in the Alpine image sorts by code point).
export const RU_COLLATION = "ru-x-icu";

/*
 * Login. The first four tables are the ones Better Auth needs, generated by its CLI
 * (`pnpm dlx auth@1.7.7 generate`) for the settings in src/lib/auth.ts, with the dates stored with
 * a time zone like everywhere else in this file. Do not rename their tables or columns: Better
 * Auth looks them up by these names.
 */
export const users = pgTable("users", {
  id: uuid()
    .default(sql`pg_catalog.gen_random_uuid()`)
    .primaryKey(),
  // Empty: the app never asks for a name.
  name: text().notNull(),
  // Stored in lower case.
  email: text().notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
});

// One row per device that is logged in.
export const sessions = pgTable(
  "sessions",
  {
    id: uuid()
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    token: text().notNull().unique(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
  },
  (t) => [index("sessions_user_id_idx").on(t.userId)],
);

// Better Auth needs it for its core; with login by email link it stays empty.
export const accounts = pgTable(
  "accounts",
  {
    id: uuid()
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
    scope: text(),
    password: text(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (t) => [index("accounts_user_id_idx").on(t.userId)],
);

// The links from the emails: `identifier` is "magic-link:" + the fingerprint of the link (the link
// itself is not stored), `value` says whose link it is.
export const verifications = pgTable(
  "verifications",
  {
    id: uuid()
      .default(sql`pg_catalog.gen_random_uuid()`)
      .primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (t) => [index("verifications_identifier_idx").on(t.identifier)],
);

// Every login email that was sent: the limit "3 per address per 10 minutes" counts these rows.
export const loginEmails = pgTable(
  "login_emails",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    email: text().notNull(),
    sentAt: timestamp("sent_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("login_emails_email_sent_at_idx").on(t.email, t.sentAt)],
);

export const contacts = pgTable(
  "contacts",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    // Whose contact this is. A user with contacts cannot be deleted from the database.
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "restrict" }),
    name: text().notNull(),
    // Who this person is: role, relation, what they do
    about: text(),
    // Where and how we met
    howWeMet: text("how_we_met"),
    phone: text(),
    email: text(),
    // How often to keep in touch; NULL means "Не задано"
    contactFrequency: text("contact_frequency", { enum: CONTACT_FREQUENCIES }),
    // Last time "Пообщались" was pressed; NULL means never
    lastContactedAt: timestamp("last_contacted_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("contacts_user_id_name_idx").on(t.userId, sql`${t.name} collate "ru-x-icu"`),
    check(
      "contacts_contact_frequency_check",
      sql`${t.contactFrequency} in (${sql.raw(CONTACT_FREQUENCIES.map((value) => `'${value}'`).join(", "))})`,
    ),
  ],
);

export const notes = pgTable(
  "notes",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    contactId: integer("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    body: text().notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("notes_contact_id_created_at_idx").on(t.contactId, t.createdAt)],
);

export const groups = pgTable(
  "groups",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    // Whose group this is. A user with groups cannot be deleted from the database.
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "restrict" }),
    name: text().notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    // Names are unique regardless of letter case within one user: "Теннис" and "теннис" are the
    // same group, but two users may both have "Друзья".
    uniqueIndex("groups_user_id_name_lower_idx").on(t.userId, sql`lower(${t.name})`),
    check("groups_name_length_check", sql`char_length(${t.name}) between 1 and 50`),
  ],
);

// Which contact is in which group. Deleting either side removes only the link.
export const groupMembers = pgTable(
  "group_members",
  {
    groupId: integer("group_id")
      .notNull()
      .references(() => groups.id, { onDelete: "cascade" }),
    contactId: integer("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.groupId, t.contactId] }),
    index("group_members_contact_id_idx").on(t.contactId),
  ],
);

export type Contact = typeof contacts.$inferSelect;
export type NewContact = typeof contacts.$inferInsert;
export type Note = typeof notes.$inferSelect;
export type Group = typeof groups.$inferSelect;
